import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
p=np.load('coords.npy');els=[s.split()[0] for s in open('answer.xyz').readlines()[2:]]
bonds=[(i,(i+1)%14) for i in range(14)]+[(n,14+j) for j,n in enumerate([0,3,7,10])]+[(50,n) for n in [0,3,7,10]]+[(50,51)]+[(51,i) for i in [52,53,54]]
